(md5('hik-q-11')::uuid, md5('hik-p-P3')::uuid, $q$Penokohan$q$, $q$Watak Inderaputera berdasarkan Bacaan 3 adalah ...$q$, $q$["penakut dan lemah", "gagah berani dan pantang menyerah", "sombong dan angkuh", "malas dan penurut"]$q$::jsonb, 1, $q$Inderaputera menumpas naga raksasa dengan pedang saktinya.$q$),
