insert into public.exams (id, nama, mapel, durasi_menit, status) values (md5('hik-exam')::uuid, 'UH Hikayat (50 soal)', 'Bahasa Indonesia', 90, 'draf') on conflict (id) do nothing;
insert into public.exam_questions (exam_id, question_id, urutan)
select md5('hik-exam')::uuid, md5('hik-q-'||n)::uuid, n from generate_series(1,50) n on conflict do nothing;
